const staticData = $getWorkflowStaticData('global');
if (!staticData.postHistory) { staticData.postHistory = []; }
// 이력이 하나도 없어도(첫 실행) 최소 1개의 결과를 반환해야 워크플로우가 멈추지 않습니다.
if (staticData.postHistory.length === 0) {
  return [{ json: { empty: true } }];
}
return staticData.postHistory.map(h => ({ json: h }));

const body = $('1. 폼 데이터 수신').first().json.body;
const direction = body.direction || '';
const angles = (body.angles || []).join(', ');
const photos = body.photos || [];

// 이전 이력 중 최근 15개만 요약 텍스트로 정리
let historyRows = $input.all().map(item => item.json);
// '1.5' 노드가 이력이 없을 때 보내는 더미 표시(empty:true)는 실제 이력이 아니므로 걸러냅니다.
historyRows = historyRows.filter(r => !r.empty);
const recentHistory = historyRows.slice(-15);
const historyText = recentHistory.length
  ? recentHistory.map(r => `- (${r['날짜']}) ${r['제목']}: ${r['요약']}`).join('\n')
  : '(아직 이력 없음)';

const contentBlocks = [];
for (const p of photos) {
  const match = /^data:(image\/\w+);base64,(.+)$/.exec(p.imageData || '');
  if (match) {
    contentBlocks.push({
      type: 'image',
      source: { type: 'base64', media_type: match[1], data: match[2] }
    });
  }
  contentBlocks.push({ type: 'text', text: `[사진 ${p.order}] 설명: ${p.caption}` });
}

contentBlocks.push({
  type: 'text',
  text: `\n전체 방향: ${direction}\n강조하고 싶은 톤: ${angles}\n\n최근에 올렸던 글 목록(참고용):\n${historyText}\n\n위 사진/설명을 바탕으로 '원하다 필라테스' 네이버 블로그 글을 작성해줘. 다음 원칙을 지켜줘:\n1. 도입부(hook): 이미 다니는 회원이 아니라, 검색으로 처음 들어온 사람도 공감할 만한 문장으로 시작 (막연한 일지체 금지)\n2. 본문: 사진 설명들을 자연스럽게 녹여서 서술하되, 왜 그 동작/수업이 도움이 되는지 이유를 함께 설명\n3. 최근 글 목록과 소재·표현·구성이 겹치지 않도록 새로운 각도로 작성\n4. 소제목마다 관련된 이모지를 하나씩 붙여서 시각적으로 스캔하기 쉽게 구성 (예: 🧱 왜 벽을 활용할까요?)\n5. 마지막에 처음 오는 사람이 다음 행동을 취하도록 유도하는 CTA 한 문장 포함 (예: 체험 문의 유도)\n\n해시태그와 문의전화·주소·영업시간은 네가 작성하지 마 — 별도로 고정 삽입돼.\n\n다음 JSON 형식으로만 응답해줘 (다른 설명 없이):\n{"title": "글 제목", "summary": "한 줄 요약(다음 번 중복 체크용, 20자 내외)", "hook": "도입부 1~2문장", "body": "본문 전체(도입부 제외), 사진은 [사진 N] 위치 표시", "cta": "마무리 유도 문장 1개"}`
});

return [{ json: { contentBlocks } }];

// content 배열 안에서 'text' 타입 블록을 명시적으로 찾습니다.
// (항상 content[0]이 텍스트라고 가정하면 안 됩니다 — 다른 블록이 먼저 올 수 있습니다)
const contentBlocks = $input.first().json.content || [];
const textBlock = contentBlocks.find(b => b && b.type === 'text');
const raw = textBlock ? textBlock.text : undefined;

if (!raw) {
  // 무엇이 왔는지 명확히 알 수 있도록 원본 응답을 에러 메시지에 그대로 포함시킵니다.
  throw new Error('Claude 응답에서 텍스트를 찾지 못했습니다. 실제 응답: ' + JSON.stringify($input.first().json).slice(0, 1000));
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { title: '제목 파싱 실패', summary: '', hook: '', body: raw, cta: '', hashtags: [] };
}

return [{ json: {
  title: parsed.title,
  summary: parsed.summary,
  hook: parsed.hook,
  body: parsed.body,
  cta: parsed.cta,
  hashtags: parsed.hashtags || [],
  date: new Date().toISOString().slice(0, 10)
} }];

// 지금은 본인 네이버 블로그로 테스트하는 단계이니, 아래 원하다 필라테스용 고정정보는
// 비워두거나 테스트용으로 바꿔서 쓰세요. 실제 어머니 블로그로 넘어갈 때 다시 채우면 됩니다.
const FOOTER = ``; // 예: `문의전화 062-511-1111 ...`
const FIXED_HASHTAGS = []; // 예: ['광주요가', '광주필라테스']

const hashtagLine = FIXED_HASHTAGS.map(h => '#' + h).join(' ');
const d = $input.first().json;

const footerText = d.cta + FOOTER + (hashtagLine ? ('\n\n' + hashtagLine) : '');

return [{ json: Object.assign({}, d, { footer: footerText }) }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.postHistory) { staticData.postHistory = []; }
const d = $('4.5 고정 안내 문구 삽입').first().json;
staticData.postHistory.push({ '날짜': d.date, '제목': d.title, '요약': d.summary });
// 최근 50개까지만 보관 (너무 오래된 건 자동 정리)
if (staticData.postHistory.length > 50) { staticData.postHistory = staticData.postHistory.slice(-50); }
return [{ json: { saved: true } }];
